export const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";
export const ACTOR_STORAGE_KEY = "cert-admin.actor";

export class ApiError extends Error {
  constructor(public status: number, public code: string, message: string) {
    super(message);
  }
}

export function readStoredActor(): string {
  try {
    return localStorage.getItem(ACTOR_STORAGE_KEY) ?? "";
  } catch {
    return "";
  }
}

async function toError(res: Response): Promise<ApiError> {
  let code = "http_error";
  let message = `${res.status} ${res.statusText}`;
  try {
    const j = await res.json();
    if (j?.detail?.code) {
      code = j.detail.code;
      message = j.detail.message;
    } else if (typeof j?.detail === "string") {
      message = j.detail;
    } else if (j?.detail) {
      message = JSON.stringify(j.detail);
    }
  } catch {
    /* non-JSON body */
  }
  return new ApiError(res.status, code, message);
}

export async function api<T>(path: string, init: RequestInit = {}, actor = readStoredActor()): Promise<T> {
  const headers = new Headers(init.headers);
  headers.set("X-Actor", actor);
  if (init.body) headers.set("Content-Type", "application/json");
  const res = await fetch(`${API_URL}${path}`, { ...init, headers });
  if (!res.ok) throw await toError(res);
  return res.json() as Promise<T>;
}

/** Export needs the X-Actor header, so it cannot be a plain link: fetch -> blob -> download. */
export async function downloadCsv(query: string) {
  const res = await fetch(`${API_URL}/api/certificates/export.csv?${query}`, {
    headers: { "X-Actor": readStoredActor() },
  });
  if (!res.ok) throw await toError(res);
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "certificates.csv";
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

export type Certificate = {
  id: number;
  serial: string;
  learner_name: string;
  course_title: string;
  status: "active" | "revoked";
  issued_at_utc: string;
  issued_at_local: string;
  issued_local_date: string;
  revoked_at_utc: string | null;
};

export type CertificateDetail = Certificate & {
  tenant: { code: string; name: string; timezone: string };
  audit: { id: number; action: string; actor_email: string; operation_id: string | null; created_at_utc: string }[];
};

export type Page<T> = { items: T[]; total: number; page: number; page_size: number };

export type BulkOutcome = {
  learner_id: number;
  learner_name: string;
  outcome: "issued" | "skipped" | "failed";
  reason: string | null;
  serial: string | null;
};

export type BulkIssueResult = {
  operation_id: string;
  course_id: number;
  course_title: string;
  summary: { issued: number; skipped: number; failed: number };
  results: BulkOutcome[];
  replayed: boolean;
};

"use client";

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
import { ACTOR_STORAGE_KEY, API_URL, readStoredActor } from "./api";

type ActorOption = { email: string; tenant_code: string };
type ActorCtx = { actor: string; setActor: (a: string) => void; options: ActorOption[]; ready: boolean };

const Ctx = createContext<ActorCtx>({ actor: "", setActor: () => {}, options: [], ready: false });

export function ActorProvider({ children }: { children: ReactNode }) {
  const [actor, setActorState] = useState("");
  const [options, setOptions] = useState<ActorOption[]>([]);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetch(`${API_URL}/api/actors`)
      .then((r) => r.json())
      .then((opts: ActorOption[]) => {
        if (cancelled) return;
        setOptions(opts);
        const stored = readStoredActor();
        const initial = opts.some((o) => o.email === stored) ? stored : (opts[0]?.email ?? "");
        setActorState(initial);
        try {
          localStorage.setItem(ACTOR_STORAGE_KEY, initial);
        } catch {}
        setReady(true);
      })
      .catch(() => setReady(true));
    return () => {
      cancelled = true;
    };
  }, []);

  const setActor = (a: string) => {
    setActorState(a);
    try {
      localStorage.setItem(ACTOR_STORAGE_KEY, a);
    } catch {}
  };

  return <Ctx.Provider value={{ actor, setActor, options, ready }}>{children}</Ctx.Provider>;
}

export const useActor = () => useContext(Ctx);

export function ActorSelector() {
  const { actor, setActor, options } = useActor();
  return (
    <label className="flex items-center gap-2 text-sm">
      <span className="text-gray-500">Acting as</span>
      <select
        className="rounded border border-gray-300 bg-white px-2 py-1"
        value={actor}
        onChange={(e) => setActor(e.target.value)}
      >
        {options.map((o) => (
          <option key={o.email} value={o.email}>
            {o.email} ({o.tenant_code})
          </option>
        ))}
      </select>
    </label>
  );
}

