"use client";

import { useEffect, useState } from "react";
import { api, ApiError, type BulkIssueResult } from "@/lib/api";
import { useActor } from "@/lib/actor";

type Course = { id: number; title: string };
type Phase = "idle" | "pending" | "done" | "error";

export function BulkIssuePanel({ onIssued }: { onIssued: () => void }) {
  const { actor } = useActor();
  const [courses, setCourses] = useState<Course[]>([]);
  const [courseId, setCourseId] = useState<number | "">("");
  // One key per logical attempt: reused on retry after a failure, rotated after success (A2/A3).
  const [idemKey, setIdemKey] = useState(() => crypto.randomUUID());
  const [phase, setPhase] = useState<Phase>("idle");
  const [result, setResult] = useState<BulkIssueResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!actor) return;
    setResult(null);
    setError(null);
    setPhase("idle");
    api<Course[]>("/api/courses", {}, actor)
      .then((c) => {
        setCourses(c);
        setCourseId(c[0]?.id ?? "");
      })
      .catch((e) => setError(e.message));
  }, [actor]);

  const submit = async () => {
    if (courseId === "" || phase === "pending") return;
    setPhase("pending");
    setError(null);
    try {
      const r = await api<BulkIssueResult>("/api/certificates/bulk-issue", {
        method: "POST",
        headers: { "Idempotency-Key": idemKey },
        body: JSON.stringify({ course_id: courseId }),
      });
      setResult(r);
      setPhase("done");
      setIdemKey(crypto.randomUUID());
      onIssued();
    } catch (e) {
      const msg = e instanceof ApiError ? `${e.code}: ${e.message}` : (e as Error).message;
      setError(msg);
      setPhase("error");
    }
  };

  return (
    <section className="rounded-lg border bg-white p-4">
      <h2 className="mb-3 font-semibold">Bulk issue</h2>
      <div className="flex flex-wrap items-center gap-3">
        <select
          className="rounded border border-gray-300 px-2 py-1"
          value={courseId}
          disabled={phase === "pending"}
          onChange={(e) => {
            setCourseId(Number(e.target.value));
            setIdemKey(crypto.randomUUID());
            setResult(null);
            setPhase("idle");
          }}
        >
          {courses.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title}
            </option>
          ))}
        </select>
        <button
          onClick={submit}
          disabled={phase === "pending" || courseId === ""}
          className="rounded bg-blue-600 px-3 py-1.5 text-sm font-medium text-white disabled:cursor-not-allowed disabled:opacity-50"
        >
          {phase === "pending" ? "Issuing…" : "Issue to all eligible learners"}
        </button>
        <span className="text-xs text-gray-500">
          {phase === "pending" && "Operation in progress — button disabled to prevent duplicate submission."}
          {phase === "error" && "Failed. Retrying reuses the same idempotency key."}
          {phase === "done" && result && (result.replayed ? "Replayed existing operation." : "Operation completed.")}
        </span>
      </div>

      {error && <p className="mt-3 rounded bg-red-50 p-2 text-sm text-red-700">{error}</p>}

      {result && (
        <div className="mt-4">
          <p className="text-sm">
            <span className="font-medium">{result.course_title}</span> — issued {result.summary.issued}, skipped{" "}
            {result.summary.skipped}, failed {result.summary.failed}
            <span className="ml-2 text-xs text-gray-400">op {result.operation_id.slice(0, 8)}</span>
          </p>
          <table className="mt-2 w-full text-sm">
            <thead className="text-left text-xs uppercase text-gray-500">
              <tr>
                <th className="py-1">Learner</th>
                <th className="py-1">Outcome</th>
                <th className="py-1">Reason</th>
                <th className="py-1">Serial</th>
              </tr>
            </thead>
            <tbody>
              {result.results.map((r) => (
                <tr key={r.learner_id} className="border-t">
                  <td className="py-1">{r.learner_name}</td>
                  <td className="py-1">
                    <OutcomeBadge outcome={r.outcome} />
                  </td>
                  <td className="py-1 text-gray-600">{r.reason ?? "—"}</td>
                  <td className="py-1 font-mono text-xs">{r.serial ?? "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

function OutcomeBadge({ outcome }: { outcome: "issued" | "skipped" | "failed" }) {
  const cls =
    outcome === "issued"
      ? "bg-green-100 text-green-800"
      : outcome === "skipped"
        ? "bg-yellow-100 text-yellow-800"
        : "bg-red-100 text-red-800";
  return <span className={`rounded px-2 py-0.5 text-xs font-medium ${cls}`}>{outcome}</span>;
}

"use client";

import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import { api, downloadCsv, type Certificate, type Page } from "@/lib/api";
import { useActor } from "@/lib/actor";
import { BulkIssuePanel } from "@/components/BulkIssuePanel";

type SortField = "issued_local_date" | "learner_name" | "serial" | "course_title" | "status";
const PAGE_SIZE = 20;

const COLUMNS: { key: SortField; label: string }[] = [
  { key: "serial", label: "Serial" },
  { key: "learner_name", label: "Learner" },
  { key: "course_title", label: "Course" },
  { key: "issued_local_date", label: "Issued (tenant local)" },
  { key: "status", label: "Status" },
];

export default function CertificateListPage() {
  const { actor, ready } = useActor();
  const [qInput, setQInput] = useState("");
  const [q, setQ] = useState("");
  const [sort, setSort] = useState<SortField>("issued_local_date");
  const [dir, setDir] = useState<"asc" | "desc">("desc");
  const [page, setPage] = useState(1);
  const [data, setData] = useState<Page<Certificate> | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [exporting, setExporting] = useState(false);
  const [reloadTick, setReloadTick] = useState(0);

  const query = new URLSearchParams({ q, sort, dir }).toString();

  useEffect(() => {
    if (!ready || !actor) return;
    let cancelled = false;
    setLoading(true);
    setError(null);
    api<Page<Certificate>>(`/api/certificates?${query}&page=${page}&page_size=${PAGE_SIZE}`, {}, actor)
      .then((d) => !cancelled && setData(d))
      .catch((e) => !cancelled && setError(e.message))
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [actor, ready, query, page, reloadTick]);

  useEffect(() => {
    setPage(1);
  }, [actor, q, sort, dir]);

  const refresh = useCallback(() => setReloadTick((t) => t + 1), []);

  const toggleSort = (key: SortField) => {
    if (key === sort) setDir(dir === "asc" ? "desc" : "asc");
    else {
      setSort(key);
      setDir(key === "issued_local_date" ? "desc" : "asc");
    }
  };

  const onExport = async () => {
    setExporting(true);
    setError(null);
    try {
      await downloadCsv(query);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setExporting(false);
    }
  };

  const totalPages = data ? Math.max(1, Math.ceil(data.total / PAGE_SIZE)) : 1;

  return (
    <div className="space-y-6">
      <BulkIssuePanel onIssued={refresh} />

      <section className="rounded-lg border bg-white p-4">
        <div className="mb-3 flex flex-wrap items-center gap-3">
          <h2 className="font-semibold">Certificates</h2>
          <form
            className="flex items-center gap-2"
            onSubmit={(e) => {
              e.preventDefault();
              setQ(qInput.trim());
            }}
          >
            <input
              className="w-64 rounded border border-gray-300 px-2 py-1 text-sm"
              placeholder="Search learner name or serial"
              value={qInput}
              onChange={(e) => setQInput(e.target.value)}
            />
            <button className="rounded border px-3 py-1 text-sm" type="submit">
              Search
            </button>
            {q && (
              <button
                type="button"
                className="text-sm text-gray-500 underline"
                onClick={() => {
                  setQInput("");
                  setQ("");
                }}
              >
                clear
              </button>
            )}
          </form>
          <div className="ml-auto flex items-center gap-3">
            {data && <span className="text-sm text-gray-500">{data.total.toLocaleString()} total</span>}
            <button
              onClick={onExport}
              disabled={exporting}
              className="rounded border px-3 py-1 text-sm disabled:opacity-50"
              title="Exports the current search and sort"
            >
              {exporting ? "Exporting…" : "Export CSV"}
            </button>
          </div>
        </div>

        {error && <p className="mb-3 rounded bg-red-50 p-2 text-sm text-red-700">Error: {error}</p>}

        <table className="w-full text-sm">
          <thead className="text-left text-xs uppercase text-gray-500">
            <tr>
              {COLUMNS.map((c) => (
                <th key={c.key} className="cursor-pointer select-none py-2" onClick={() => toggleSort(c.key)}>
                  {c.label}
                  {sort === c.key && <span className="ml-1">{dir === "asc" ? "▲" : "▼"}</span>}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {loading && (
              <tr>
                <td colSpan={5} className="py-8 text-center text-gray-500">
                  Loading…
                </td>
              </tr>
            )}
            {!loading && !error && data && data.items.length === 0 && (
              <tr>
                <td colSpan={5} className="py-8 text-center text-gray-500">
                  {q ? `No certificates match “${q}”.` : "No certificates yet. Use bulk issue above."}
                </td>
              </tr>
            )}
            {!loading &&
              data?.items.map((c) => (
                <tr key={c.id} className="border-t hover:bg-gray-50">
                  <td className="py-2 font-mono text-xs">
                    <Link className="text-blue-700 underline" href={`/certificates/${c.id}`}>
                      {c.serial}
                    </Link>
                  </td>
                  <td className="py-2">{c.learner_name}</td>
                  <td className="py-2">{c.course_title}</td>
                  <td className="py-2">{c.issued_at_local}</td>
                  <td className="py-2">
                    <StatusBadge status={c.status} />
                  </td>
                </tr>
              ))}
          </tbody>
        </table>

        <div className="mt-3 flex items-center justify-end gap-3 text-sm">
          <button className="rounded border px-2 py-1 disabled:opacity-40" disabled={page <= 1 || loading} onClick={() => setPage(page - 1)}>
            ‹ Prev
          </button>
          <span>
            Page {page} of {totalPages}
          </span>
          <button
            className="rounded border px-2 py-1 disabled:opacity-40"
            disabled={page >= totalPages || loading}
            onClick={() => setPage(page + 1)}
          >
            Next ›
          </button>
        </div>
      </section>
    </div>
  );
}

export function StatusBadge({ status }: { status: "active" | "revoked" }) {
  const cls = status === "active" ? "bg-green-100 text-green-800" : "bg-gray-200 text-gray-700";
  return <span className={`rounded px-2 py-0.5 text-xs font-medium ${cls}`}>{status}</span>;
}

"use client";

import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { api, type CertificateDetail } from "@/lib/api";
import { useActor } from "@/lib/actor";

export default function CertificateDetailPage() {
  const { id } = useParams<{ id: string }>();
  const { actor, ready } = useActor();
  const [cert, setCert] = useState<CertificateDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [revoking, setRevoking] = useState(false);

  useEffect(() => {
    if (!ready || !actor) return;
    let cancelled = false;
    setLoading(true);
    setError(null);
    api<CertificateDetail>(`/api/certificates/${id}`, {}, actor)
      .then((c) => !cancelled && setCert(c))
      .catch((e) => {
        if (cancelled) return;
        setCert(null);
        setError(e.message);
      })
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [id, actor, ready]);

  const revoke = async () => {
    if (!cert || !confirm(`Revoke certificate ${cert.serial} for ${cert.learner_name}? This cannot be undone.`)) return;
    setRevoking(true);
    setError(null);
    try {
      setCert(await api<CertificateDetail>(`/api/certificates/${id}/revoke`, { method: "POST" }, actor));
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setRevoking(false);
    }
  };

  return (
    <div className="space-y-4">
      <Link href="/" className="text-sm text-blue-700 underline">
        ← Back to list
      </Link>
      {loading && <p className="text-gray-500">Loading…</p>}
      {error && <p className="rounded bg-red-50 p-2 text-sm text-red-700">Error: {error}</p>}
      {cert && (
        <>
          <section className="rounded-lg border bg-white p-4">
            <div className="flex items-start justify-between">
              <h1 className="font-mono text-lg">{cert.serial}</h1>
              <span
                className={`rounded px-2 py-0.5 text-xs font-medium ${
                  cert.status === "active" ? "bg-green-100 text-green-800" : "bg-gray-200 text-gray-700"
                }`}
              >
                {cert.status}
              </span>
            </div>
            <dl className="mt-4 grid grid-cols-[10rem_1fr] gap-y-2 text-sm">
              <dt className="text-gray-500">Learner</dt>
              <dd>{cert.learner_name}</dd>
              <dt className="text-gray-500">Course</dt>
              <dd>{cert.course_title}</dd>
              <dt className="text-gray-500">Tenant</dt>
              <dd>
                {cert.tenant.name} ({cert.tenant.timezone})
              </dd>
              <dt className="text-gray-500">Issued (tenant local)</dt>
              <dd>
                {cert.issued_at_local} <span className="text-gray-400">· {cert.issued_at_utc} UTC</span>
              </dd>
              {cert.revoked_at_utc && (
                <>
                  <dt className="text-gray-500">Revoked (UTC)</dt>
                  <dd>{cert.revoked_at_utc}</dd>
                </>
              )}
            </dl>
            {cert.status === "active" && (
              <button
                onClick={revoke}
                disabled={revoking}
                className="mt-4 rounded bg-red-600 px-3 py-1.5 text-sm font-medium text-white disabled:opacity-50"
              >
                {revoking ? "Revoking…" : "Revoke certificate"}
              </button>
            )}
          </section>

          <section className="rounded-lg border bg-white p-4">
            <h2 className="mb-2 font-semibold">Audit trail</h2>
            <table className="w-full text-sm">
              <thead className="text-left text-xs uppercase text-gray-500">
                <tr>
                  <th className="py-1">When (UTC)</th>
                  <th className="py-1">Action</th>
                  <th className="py-1">Actor</th>
                  <th className="py-1">Operation</th>
                </tr>
              </thead>
              <tbody>
                {cert.audit.map((a) => (
                  <tr key={a.id} className="border-t">
                    <td className="py-1">{a.created_at_utc}</td>
                    <td className="py-1">{a.action}</td>
                    <td className="py-1">{a.actor_email}</td>
                    <td className="py-1 font-mono text-xs text-gray-500">{a.operation_id ?? "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
        </>
      )}
    </div>
  );
}

